#[test]
fn sd_g5_a_row_the_candidate_cannot_publish_sets_no_s_star() {
    // RV19-D4 (ROOT's ruling on RV19's delta check): O9 on the stop rule is
    // keyed on the candidate's binary64 value, as the classification's is on
    // the published one. Row 0 straddles binary64's range, its candidate on
    // one side and its verification on the other; row 1's allowance
    // 2^-64·max(|q_2p|, S*) shows whether row 0 set S*. Keyed on the
    // verification instead, every verdict below turns over.
    let mut ctx = WideContext::<4>::new(256).unwrap();
    let w = |e: i64| Wide::<4>::ONE.mul_pow2(e).unwrap();
    // Overflow: T = 2^1024 − 2^970, binary64's threshold (a tie that rounds
    // to 2^1024); T − 2^950 rounds to f64::MAX.
    let t = ctx.sub(&w(1024), &w(970)).unwrap();
    let below_t = ctx.sub(&t, &w(950)).unwrap();
    assert!(t.to_binary64().value().is_none());
    assert!(below_t.to_binary64().value().is_some());
    let (layout, r) = two_displacement_rows([Component::Ux, Component::Uy]);
    let one = Wide::<4>::ONE;
    let off = ctx.add(&one, &w(-40)).unwrap();
    // The candidate overflows, its verification does not: row 0 sets no S*,
    // so row 1's |Δ| = 2^-40 meets S* = 1 and is rejected.
    assert_eq!(
        verdict2(&layout, &[t, off], &[below_t, one], &r),
        Some(Rejection::StopRule { index: 1 })
    );
    // The verification overflows, the candidate does not: row 0 sets S*
    // (about 2^1024), and row 1 passes against it.
    assert_eq!(verdict2(&layout, &[below_t, off], &[t, one], &r), None);

#[test]
fn the_sas_norm_is_the_larger_of_the_one_and_infinity_norms() {
    // RV19-5 (ROOT's ruling): R7 item 6 takes ‖SĀS‖ as the larger of the
    // 1-norm and the ∞-norm, since Lemma C uses the 1-norm and the Theorem's
    // step 5 the ∞-norm. On the controls Ā's triangles differ only by the
    // rounding of |D|B̄ and the ∞-norm is never the smaller, so here one
    // transposed entry of N05's Ā at 256 is raised by 2^20: a column sum then
    // exceeds every row sum, and the block's norm must be the 1-norm.
    let prep = CasePrep::new(models::model("N05").source()).unwrap();
    let group = prepare_group(&prep.source).unwrap();
    let guard = StageGuard::unlimited();
    let shared = build_shared::<4, 8>(256, 320, &prep.source, &group, guard)
        .result
        .unwrap();
    let state = solve_case_at::<4, 8>(&shared, &prep, &group, guard)
        .result
        .unwrap();
    let mut vs = build_verify_shared::<4, 8, 8>(&shared, &prep.source, &group, guard)
        .result
        .unwrap();
    let pattern = &group.structure.pattern;
    let position = &group.ordering.position;
    let mut found = 0;
    for &g in &group.ordering.free {
        for index in pattern.row_range(g) {
            let j = pattern.column(index);
            if j == g || position[j] == usize::MAX {
                continue;
            }
            let t = pattern.transpose(index);
            let original = vs.abar[t];
            if original.is_zero() {
                continue;
            }
            vs.abar[t] = original.mul_pow2(20).unwrap();
            let r = verify_state::<4, 8, 8>(&shared, &vs, &prep, &group, &state, guard)
                .result
                .unwrap();
            vs.abar[t] = original;
            for n in &r.norms {
                let one_larger = n.sas_one.cmp_value(&n.sas_inf) == std::cmp::Ordering::Greater;
                let larger = if one_larger { &n.sas_one } else { &n.sas_inf };
                assert_eq!(n.sas.cmp_value(larger), std::cmp::Ordering::Equal);
                found += usize::from(one_larger);
            }
        }
    }
    assert!(found > 0, "no entry makes the 1-norm the larger");

#[test]
fn pc21_24_floor_precision_kind_and_original_coupling() {
    let f = zero_pair(128);
    assert!(matches!(
        certify_publication(
            &f.prep,
            &f.candidate,
            &f.verification,
            &f.report,
            Some(&[[0.0, 0.0]]),
            StageGuard::unlimited()
        )
        .result,
        Err(AttemptStop::PublicationCertificate {
            issue: CertificateIssue::Shape,
            ..
        })
    ));
    let f = zero_pair(512);
    assert!(matches!(
        certify_publication(
            &f.prep,
            &f.candidate,
            &f.verification,
            &f.report,
            None,
            StageGuard::unlimited()
        )
        .result,
        Err(AttemptStop::PublicationCertificate {
            issue: CertificateIssue::Shape,
            ..
        })
    ));
    for floor in [
        [0.0, 0.0],
        [f64::from_bits(1), f64::from_bits(1)],
        [8.0, 16.0],
    ] {
        let spent = certify_publication(
            &f.prep,
            &f.candidate,
            &f.verification,
            &f.report,
            Some(&[floor]),
            StageGuard::unlimited(),
        );
        let Ok(PublicationDecision::Accepted(d)) = spent.result else {
            panic!("zero source with valid p512 floor");
        };
        assert_eq!(d.publication.body_scales[0].2, 0);
        assert_eq!(d.publication.body_scales[1].2, 0);
        assert_eq!(d.publication.body_scales[2].2, floor[0].to_bits());
        assert_eq!(d.publication.body_scales[3].2, floor[1].to_bits());
    }
    let metas = [meta(Kind::Force), meta(Kind::Moment)];
    let values = [Binary64Outcome::Normal(2.0), Binary64Outcome::Normal(1.0)];
    let pub_ = classify_rows_floored(&metas, &values, &[2.0], Some(&[[8.0, 0.0]]));
    assert_eq!(pub_.body_scales[2].2, 8.0f64.to_bits());
    assert_eq!(pub_.body_scales[3].2, 4.0f64.to_bits()); // not L*floor_force

